&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html&quot; title=&quot;Les monstres mythiques&quot;&gt;Les monstres mythiques&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;4&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;Arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique.html&quot; title=&quot;Construire une cr&#233;ature mythique&quot;&gt;Construire une cr&#233;ature mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;Le sous-type mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-De-Monstres-Mythiques-Universelles.html&quot; title=&quot;R&#232;gles de monstres mythiques universelles&quot;&gt;R&#232;gles de monstres mythiques universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;&#201;valuer les statistiques des monstres&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Monstres-Mythiques.html&quot; title=&quot;Liste alphab&#233;tique des monstres mythiques&quot;&gt;Liste des monstres mythiques&lt;/a&gt;&lt;/li&gt;
